// grep-lite.js — usage: node grep-lite.js --ignore-case error < app.log
import { parseArgs, styleText } from "node:util";
import { createInterface } from "node:readline/promises";

const { values, positionals } = parseArgs({
  options: {
    "ignore-case": { type: "boolean", short: "i", default: false },
    max: { type: "string", default: "100" },
  },
  allowPositionals: true,
});

const [pattern] = positionals;
if (!pattern) {
  console.error("usage: grep-lite [-i] [--max N] <pattern>");
  process.exit(2);
}
const re = new RegExp(pattern, values["ignore-case"] ? "i" : "");
let hits = 0;

const rl = createInterface({ input: process.stdin });
for await (const line of rl) {
  if (re.test(line) && hits++ < Number(values.max)) console.log(styleText("yellow", line));
}

