import { EventEmitter, once } from "node:events";

class Job extends EventEmitter {
  async run(steps) {
    for (let i = 1; i <= steps; i++) {
      await new Promise((r) => setTimeout(r, 50));
      this.emit("progress", i, steps);
    }
    if (steps > 3) this.emit("error", new Error("too many steps"));
    else this.emit("done", { steps });
  }
}

const job = new Job();
job.on("progress", (i, n) => console.log(`step ${i}/${n}`));
job.on("error", (err) => console.error("job failed:", err.message)); // without this: crash

job.run(3);
const [result] = await once(job, "done");   // promise-style wait
console.log("finished", result);            // finished { steps: 3 }

import { createReadStream, createWriteStream } from "node:fs";
import { pipeline } from "node:stream/promises";
import { createGzip } from "node:zlib";
import { writeFile } from "node:fs/promises";

await writeFile("access.log", "GET /\nPOST /login\nGET /about\n".repeat(1000));

// Async-generator stage: keep only GET lines, uppercase them
async function* onlyGets(source) {
  let rest = "";
  for await (const chunk of source) {
    const lines = (rest + chunk).split("\n");
    rest = lines.pop();                         // keep a partial last line
    for (const line of lines) if (line.startsWith("GET")) yield line.toUpperCase() + "\n";
  }
}

await pipeline(
  createReadStream("access.log", { encoding: "utf8" }),
  onlyGets,
  createGzip(),
  createWriteStream("gets.log.gz"),
);
console.log("done");   // errors in any stage reject the pipeline promise

import { createServer } from "node:http";

const todos = [{ id: 1, title: "learn node:http" }];
async function readJson(req, limit = 1_000_000) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    if ((size += chunk.length) > limit) throw Object.assign(new Error("too large"), { status: 413 });
    chunks.push(chunk);
  }
  return JSON.parse(Buffer.concat(chunks).toString("utf8"));
}
const send = (res, status, data) =>
  res.writeHead(status, { "content-type": "application/json" }).end(JSON.stringify(data));

const server = createServer(async (req, res) => {
  try {
    const { pathname } = new URL(req.url, "http://localhost");
    if (req.method === "GET" && pathname === "/todos") return send(res, 200, todos);
    if (req.method === "POST" && pathname === "/todos") {
      const todo = { id: todos.length + 1, title: (await readJson(req)).title };
      todos.push(todo);
      return send(res, 201, todo);
    }
    send(res, 404, { error: "not found" });
  } catch (err) {
    send(res, err.status ?? (err instanceof SyntaxError ? 400 : 500), { error: err.message });
  }
});
server.listen(3000, () => console.log("http://localhost:3000/todos"));

class HttpError extends Error {
  constructor(res, body) {
    super(`HTTP ${res.status} for ${res.url}`);
    this.status = res.status;
    this.body = body;
  }
}

async function getJson(url, { timeoutMs = 5000, ...init } = {}) {
  const res = await fetch(url, {
    ...init,
    headers: { accept: "application/json", ...init.headers },
    signal: AbortSignal.timeout(timeoutMs),
  });
  if (!res.ok) throw new HttpError(res, await res.text());  // fetch doesn't throw on 4xx/5xx
  return res.json();
}

