// fib-worker.js — one file acting as both main thread and worker
import { Worker, isMainThread, parentPort, workerData } from "node:worker_threads";

function fib(n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }   // deliberately slow

if (isMainThread) {
  const runFib = (n) => new Promise((resolve, reject) => {
    const worker = new Worker(new URL(import.meta.url), { workerData: n });
    worker.once("message", resolve);
    worker.once("error", reject);
  });

  const ticker = setInterval(() => console.log("main thread still responsive"), 200);
  console.log("fib(40) =", await runFib(40));   // computed on another thread
  clearInterval(ticker);
} else {
  parentPort.postMessage(fib(workerData));
}

import { Transform, Readable } from "node:stream";
import { pipeline } from "node:stream/promises";
import { createWriteStream } from "node:fs";

// Transform: object rows -> CSV lines, with a header emitted lazily
class ToCsv extends Transform {
  constructor() { super({ writableObjectMode: true }); this.header = false; }
  _transform(row, _enc, callback) {
    if (!this.header) { this.push(Object.keys(row).join(",") + "\n"); this.header = true; }
    callback(null, Object.values(row).join(",") + "\n");
  }
  _flush(callback) { this.push("# end\n"); callback(); }
}

// A large lazy source: rows are produced only as fast as the file accepts them
function* rows(n) { for (let i = 0; i < n; i++) yield { id: i, square: i * i }; }

await pipeline(Readable.from(rows(1_000_000)), new ToCsv(), createWriteStream("squares.csv"));
console.log("rss MB:", Math.round(process.memoryUsage().rss / 1e6));  // bounded, whatever n is

