// cluster-server.js — one HTTP worker per core
import cluster from "node:cluster";
import { createServer } from "node:http";
import { availableParallelism } from "node:os";

if (cluster.isPrimary) {
  const n = availableParallelism();
  console.log(`primary ${process.pid} forking ${n} workers`);
  for (let i = 0; i < n; i++) cluster.fork();

  cluster.on("exit", (worker, code) => {
    console.log(`worker ${worker.process.pid} exited (${code}); replacing`);
    cluster.fork();
  });
} else {
  let served = 0;                                   // per-process state, NOT shared!
  createServer((req, res) => {
    res.end(`pid ${process.pid} served ${++served}\n`);
  }).listen(3000);
}
