import dc from "node:diagnostics_channel";

// --- library side ---
const queryChannel = dc.tracingChannel("mydb:query");

async function query(sql) {
  return queryChannel.tracePromise(async () => {
    await new Promise((r) => setTimeout(r, 20));      // pretend to hit a DB
    if (sql.includes("DROP")) throw new Error("nope");
    return [{ ok: 1 }];
  }, { sql });                                         // context shared by all events
}

// --- tool side (e.g. an APM agent) ---
queryChannel.subscribe({
  start(ctx) { ctx.startedAt = performance.now(); },
  asyncEnd(ctx) {
    const ms = (performance.now() - ctx.startedAt).toFixed(1);
    console.log(`${ctx.sql} took ${ms} ms${ctx.error ? " (failed)" : ""}`);
  },
  error(ctx) { console.log("error:", ctx.error.message); },
});

await query("SELECT 1");
await query("DROP TABLE x").catch(() => {});

import { createServer } from "node:http";
import { setTimeout as sleep } from "node:timers/promises";

let shuttingDown = false;
const db = { close: async () => { await sleep(50); console.log("db pool closed"); } };

const server = createServer(async (req, res) => {
  if (req.url === "/ready") return res.writeHead(shuttingDown ? 503 : 200).end();
  await sleep(1000);                       // simulate slow work
  res.end("done\n");
}).listen(3000);

async function shutdown(signal) {
  if (shuttingDown) return;                // idempotent
  shuttingDown = true;
  console.log(`${signal}: draining`);
  setTimeout(() => process.exit(1), 10_000).unref();   // safety net
  await sleep(2000);                       // let the load balancer see /ready = 503
  const closed = new Promise((resolve) => server.close(resolve)); // also drops idle sockets
  const force = setTimeout(() => server.closeAllConnections(), 5000);
  await closed;                            // in-flight requests have finished
  clearTimeout(force);
  await db.close();
  console.log("bye");                      // loop empties; exit code 0
}
process.on("SIGTERM", shutdown);
process.on("SIGINT", shutdown);
